#include "elit21/shopify/webhooks/ShopifyWebhookSignatureVerifier.h"
#include "elit21/security/Crypto.h"
#include "elit21/util/StringUtil.h"
namespace elit21::shopify::webhooks {ShopifyWebhookSignatureVerifier::ShopifyWebhookSignatureVerifier():platform::BusinessComponent("ShopifyWebhookSignatureVerifier","Constant-time Shopify HMAC verifier",platform::BusinessComponentSpec{"shopify","verify_webhook_hmac",{},false,true,16U*1024U*1024U}){}ShopifyWebhookSignatureVerifier::ShopifyWebhookSignatureVerifier(std::string secret):ShopifyWebhookSignatureVerifier(){setSecret(std::move(secret));}void ShopifyWebhookSignatureVerifier::setSecret(std::string secret){secret_=std::move(secret);}bool ShopifyWebhookSignatureVerifier::verify(const IncomingRequest&r)const{auto it=r.headers.find("x-shopify-hmac-sha256");return it!=r.headers.end()&&verify(r.body,it->second);}bool ShopifyWebhookSignatureVerifier::verify(const std::string&body,const std::string&signature)const{if(secret_.empty()||body.empty()||signature.empty())return false;return crypto::constantTimeEquals(util::trim(signature),crypto::hmacSha256Base64(secret_,body));}platform::OperationResult ShopifyWebhookSignatureVerifier::execute(const platform::OperationContext&context){auto r=executeBusiness(context);r.metrics["secret_configured"]=secret_.empty()?0.0:1.0;r.attributes["comparison"]="constant_time";return r;}}
